import java.util.*;

class Solution {
    public int findPeakElement(int[] heights) {
        int lo = 0, hi = heights.length - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (heights[mid] < heights[mid + 1]) lo = mid + 1; // still climbing
            else hi = mid;                                     // going down: summit at mid or left
        }
        return lo;
    }
}

